schema:
{
  "description": "Trasforma lo scontrino in una riga della nota spese, scegliendo per ogni campo il metodo giusto.",
  "baseAnalyzerId": "prebuilt-document",
  "config": {
    "estimateFieldSourceAndConfidence": true
  },
  "fieldSchema": {
    "fields": {
      "CategoriaSpesa": {
        "type": "string",
        "method": "classify",
        "description": "Dal tipo di esercente: è una classificazione.",
        "enum": [
          "pasti",
          "trasporti",
          "alloggio",
          "altro"
        ]
      },
      "MetodoPagamento": {
        "type": "string",
        "method": "classify",
        "description": "\"CONTANTE\" è una scelta tra due valori.",
        "enum": [
          "contanti",
          "carta"
        ]
      },
      "Totale": {
        "type": "number",
        "method": "extract",
        "description": "Importo dopo \"TOTALE COMPLESSIVO\"."
      },
      "AliquotaIVA": {
        "type": "number",
        "method": "extract",
        "description": "Aliquota IVA indicata, in percentuale."
      },
      "Esercente": {
        "type": "string",
        "method": "extract",
        "description": "Il nome in testa allo scontrino."
      },
      "Data": {
        "type": "date",
        "method": "extract",
        "description": "Con type \"date\" il servizio normalizza la data da sé."
      }
    }
  }
}
